"""Apply exact, fail-closed edits to the restored boundary-repair kernel."""
from pathlib import Path
import sys
p=Path(sys.argv[1])
s=p.read_text()
def replace(old,new):
    global s
    if s.count(old)!=1:
        raise RuntimeError(f"Expected one source anchor: {old[:100]}")
    s=s.replace(old,new,1)
replace("    bool immediate_boundary_repair=false;", "    bool immediate_boundary_repair=false, adaptive_boundary_repair=false;")
replace("    int discover(double fraction=.50,double maximum=.6,int responsive=0){", "    // Evaluate certified guards on the original CNF; retain only measured seed\n    // improvements. All conditional propagations and candidate states stay local.\n    bool try_adaptive_repair(const F& accepted,const toolbox::Model& seed,Time until){\n        if(seed.size()!=size_t(original.n+1)||Clock::now()>=until)return false;\n        for(int v=1;v<=original.n;++v)if(seed[v]!=0&&seed[v]!=1)return false;\n        auto bad=[&](const toolbox::Model& m){\n            return int(std::count_if(original.cs.begin(),original.cs.end(),[&](const C& c){\n                return std::none_of(c.begin(),c.end(),[&](int l){return toolbox::value(m,l)==1;});\n            }));\n        };\n        toolbox::Model best=seed;\n        int best_bad=bad(best), initial=best_bad, attempts=0, improvements=0;\n        if(!best_bad)return model(best,\"adaptive_boundary_source_model\");\n        toolbox::AdaptivePropagator propagator(original.n,all);\n        set<pair<size_t,int>> visited;\n        for(int round=0;round<4&&attempts<8&&Clock::now()<until;++round){\n            vector<tuple<int,size_t,int>> proposals;\n            vector<size_t> order;\n            for(size_t j=0;j<accepted.size();++j){\n                const C& g=accepted[j];\n                if(!g.empty()&&active_known.count(g)&&std::none_of(g.begin(),g.end(),\n                    [&](int l){return toolbox::value(best,l)==1;}))order.push_back(j);\n            }\n            stable_sort(order.begin(),order.end(),[&](size_t a,size_t b){\n                return accepted[a].size()<accepted[b].size();\n            });\n            int scored=0;\n            for(size_t j:order){\n                for(int l:accepted[j]){\n                    if(scored>=24||Clock::now()>=until)break;\n                    if(visited.count({j,l}))continue;\n                    auto probe=best;probe[abs(l)]=l>0;\n                    proposals.emplace_back(bad(probe),j,l);++scored;\n                }\n                if(scored>=24||Clock::now()>=until)break;\n            }\n            sort(proposals.begin(),proposals.end());\n            if(proposals.empty())break;\n            bool improved=false;\n            for(auto [score,j,pivot]:proposals){\n                (void)score;\n                if(attempts>=8||Clock::now()>=until)break;\n                visited.insert({j,pivot});++attempts;\n                C assumptions;\n                for(int l:accepted[j])if(l!=pivot)assumptions.push_back(-l);\n                if(!propagator.consistent(assumptions)){\n                    std::fprintf(stderr,\"ADAPTIVE conflict=1 round=%d attempt=%d\\n\",round,attempts);\n                    continue;\n                }\n                if(toolbox::value(propagator.state,pivot)!=1)\n                    throw std::logic_error(\"adaptive guard failed to propagate\");\n                auto candidate=best;\n                for(int l:propagator.trail)candidate[abs(l)]=l>0;\n                int before=bad(candidate);\n                const auto saved_progress=live_repair;\n                // Short slices prevent one unsuccessful pivot consuming the whole allowance.\n                auto slice=min(until,toolbox::after(.020));\n                if(before&&Clock::now()<slice)\n                    repair_feedback(original.n,original.cs,candidate,propagator.state,slice);\n                live_repair=saved_progress;\n                int after=bad(candidate);\n                bool solved=after==0&&model(candidate,\"adaptive_boundary_source_model\");\n                std::fprintf(stderr,\"ADAPTIVE attempt=%d round=%d width=%zu best_before=%d propagated_bad=%d final_bad=%d model=%d\\n\",\n                    attempts,round,accepted[j].size(),best_bad,before,after,solved);\n                if(solved)return true;\n                if(after<best_bad){\n                    best=move(candidate);best_bad=after;++improvements;improved=true;\n                    // A changed seed changes pivot utility: allow reconsideration.\n                    visited.clear();break;\n                }\n            }\n            if(!improved)break;\n        }\n        std::fprintf(stderr,\"ADAPTIVE summary=1 initial_bad=%d best_bad=%d attempts=%d improvements=%d\\n\",\n                     initial,best_bad,attempts,improvements);\n        return false;\n    }\n    int discover(double fraction=.50,double maximum=.6,int responsive=0){")
replace("        immediate_boundary_repair=schedule==\"boundary-repair\";", "        adaptive_boundary_repair=schedule==\"adaptive-repair\";\n        immediate_boundary_repair=schedule==\"boundary-repair\"||adaptive_boundary_repair;")
replace("               try_boundary_repair(accepted,boundary_seed,budget(.12,.12)))return 10;", "               (adaptive_boundary_repair?try_adaptive_repair(accepted,boundary_seed,budget(.12,.12)):\n                try_boundary_repair(accepted,boundary_seed,budget(.12,.12))))return 10;")
replace('        write_file(out/"repair.model",artifact);','        write_file(out/"repair.model",artifact);\n        if(!try_adaptive_repair(F{{2}},test_seed,toolbox::after(1)))\n            throw runtime_error("adaptive selftest: missing source model");\n        write_file(out/"adaptive.model",artifact);')
replace('            throw runtime_error("repair selftest: inconsistent conditional branch");','            throw runtime_error("repair selftest: inconsistent conditional branch");\n        if(try_adaptive_repair(F{{2}},test_seed,toolbox::after(1)))\n            throw runtime_error("adaptive selftest: inconsistent conditional branch");')
p.write_text(s)
